\label{lem:coeffbound}
If $f=\sum_{F\in\mathcal F^\sigma_\ell}c_F\,F$ in $\mathcal A^\sigma$, then
$f\le\max_{F\in\mathcal F^\sigma_\ell}c_F$.

\label{prop:maxstat}
Every maximizer of $\phi\mapsto\phi(\rho)$ on $\operatorname{Hom}^+(\mathcal A^0,\mathbb R)$ is
degree-stationary.

\label{prop:type-symmetry}
Let $G\in\mathcal F^0_7$.  For each five-vertex set $U\subseteq V(G)$
with $G[U]\cong\sigma$, choose a labeling
$\theta_U:[5]\hookrightarrow V(G)$ with image $U$ that induces
$\sigma$.  Let $\{x_U,y_U\}=V(G)\setminus U$ and set
$i_U=i(\theta_U,x_U)$ and $j_U=i(\theta_U,y_U)$.  Then,
\begin{equation}\label{eq:fiveorbit}
 T_\sigma(G;Q_b)=\sum_{\substack{U\subseteq V(G),\ |U|=5\\G[U]\cong\sigma}}
                  (\widehat Q_b)_{i_U,j_U}.
\end{equation}
Each summand is independent of the choice of $\theta_U$ and of
the ordering of $x_U,y_U$.
